new_string:
await _fetchActivePet();

if (!mounted) return;
setState(() => _isInteracting = false);

final petId = _activePet?['id']?.toString() ?? petId.toString();
final today = _todayDateStr();
if (isPlay) {
  await _showInteractionStatusMessage(
    _interactionPlaySuccessMessage(),
    eventKey: 'play:$petId:$today',
  );
} else {
  await _showInteractionStatusMessage(
    _interactionPettingSuccessMessage(),
    eventKey: 'pet:$petId:$today',
  );
}

await _syncStageAfterAffectionChange(beforeStage: beforeStage);
